export type Role = 'STUDENT' | 'LECTURER' | 'ADMIN';

// Two models, each with its own copy of id + createdAt. One copy already drifted.
export interface User {
  readonly id: number;
  readonly createdAt: string;
  email: string;
  role: Role;
}

export interface Lab {
  id: string;
  createdAt: string;
  code: string;
  capacity: number;
}

export function age(e: { createdAt: string }, now: string): number {
  return (Date.parse(now) - Date.parse(e.createdAt)) / 86400000;
}

import { age } from '../src/model.ts';
import type { Entity, User, Lab } from '../src/model.ts';

const u: User = { id: 1, createdAt: '2026-11-01T00:00:00Z', email: 'an.nv@fpt.edu.vn', role: 'STUDENT' };
const lab: Lab = { id: 7, createdAt: '2026-10-01T00:00:00Z', code: 'AL-301', capacity: 30 };
const all: Entity[] = [u, lab];
console.log(all.map((e) => age(e, '2026-11-02T00:00:00Z')));

import type { User, Lab } from '../src/model.ts';

declare const u: User;
declare const lab: Lab;
const ghost: Lab = { id: 'AL-301', createdAt: '2026-10-01', code: 'AL-301', capacity: 30 }; // expect TS2322
const noDate: User = { id: 2, email: 'b@fpt.edu.vn', role: 'LECTURER' }; // expect TS2741
lab.id = 8; // expect TS2540
u.createdAt = 'now'; // expect TS2540
export { ghost, noDate };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { age } from '../src/model.ts';

test('age in days', () => assert.equal(age({ id: 1, createdAt: '2026-11-01T00:00:00Z' }, '2026-11-03T00:00:00Z'), 2));

