import { LAB_NAMES } from './model.ts';
import type { BookingRecord, User } from './model.ts';

// What the admin list shows. Written by hand — and already behind: BookingRecord has userId and seats now.
export interface BookingView {
  id: number;
  lab: string;
  labName: string;
  userName: string;
}

export function toView(b: BookingRecord, users: readonly User[]): BookingView {
  return {
    id: b.id,
    lab: b.lab,
    labName: LAB_NAMES[b.lab] ?? b.lab,
    userName: users.find((u) => u.id === b.userId)?.name ?? '(deleted user)',
  };
}

// Given — do not edit.
export interface BookingRecord {
  readonly id: number;
  readonly lab: string;
  readonly userId: number;
  readonly seats: number;
}
export interface User {
  readonly id: number;
  name: string;
}
export const LAB_NAMES: { [code: string]: string } = { 'BE-201': 'Backend Lab 1', 'AL-301': 'AI Lab' };

import { toView } from '../src/view.ts';
import type { BookingView } from '../src/view.ts';

const view: BookingView = toView({ id: 11, lab: 'AL-301', userId: 2, seats: 25 }, [{ id: 2, name: 'Tran Thi Binh' }]);
const seats: number = view.seats;
console.log(view.labName, seats);

import type { BookingView } from '../src/view.ts';

const noName: BookingView = { id: 1, lab: 'BE-201', userId: 1, seats: 5, labName: 'Backend Lab 1' }; // expect TS2322
const noSeats: BookingView = { id: 1, lab: 'BE-201', userId: 1, labName: 'Backend Lab 1', userName: 'An' }; // expect TS2322
export { noName, noSeats };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toView } from '../src/view.ts';

test('every record field plus two names', () => assert.deepEqual(
  toView({ id: 11, lab: 'AL-301', userId: 2, seats: 25 }, [{ id: 2, name: 'Tran Thi Binh' }]),
  { id: 11, lab: 'AL-301', userId: 2, seats: 25, labName: 'AI Lab', userName: 'Tran Thi Binh' },
));
test('a deleted user', () => assert.equal(toView({ id: 12, lab: 'BE-201', userId: 9, seats: 5 }, []).userName, '(deleted user)'));

