// Interfaces with extends report a conflict at the declaration (TS2430) instead of hiding a never.
export interface Entity { readonly id: number; readonly createdAt: string }
export interface Lab extends Entity { code: string; capacity: number }
// The supplier's code is a different fact, so it has its own name; equipment keeps a numeric id.
export interface Equipment extends Entity { supplierCode: string; labCode: string; name: string }

export const LAB: Lab = { id: 1, createdAt: '2026-11-01', code: 'AL-301', capacity: 30 };
export const GPU: Equipment = { id: 42, supplierCode: 'EQ-0042', createdAt: '2026-11-01', labCode: 'AL-301', name: 'GPU server' };

import type { Equipment } from '../src/model.ts';

const textId: Equipment = { id: 'EQ-0043', supplierCode: 'EQ-0043', createdAt: '2026-11-01', labCode: 'BE-201', name: 'Printer' }; // expect TS2322
const noCode: Equipment = { id: 43, createdAt: '2026-11-01', labCode: 'BE-201', name: 'Printer' }; // expect TS2741
export { textId, noCode };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { LAB, GPU } from '../src/model.ts';

test('every entity has a numeric id', () => assert.ok([LAB, GPU].every((e) => typeof e.id === 'number')));
test('the supplier code is kept', () => assert.equal(GPU.supplierCode, 'EQ-0042'));

